"""M5 device-id (v1): the worker client's stable per-device identity.

The Alice ADDRESS stays the worker's credit/payout identity, but the unit of
MEASUREMENT/scoring/economics is the DEVICE. So a worker client generates a
STABLE random device id ONCE (on first run), persists it locally, and reuses it
on every subsequent run. The mining-worker name is then
``{alice_address}.{device_id}`` (see
:func:`alice_acp.api_chat_gateway.worker_pull_protocol.device_worker_name`), so
the account-poll attribution (the M4 fix) attributes mining PER DEVICE while
credit still accrues to the address.

Design (V-confirmed):

* The id is a Python ``uuid4().hex`` (32 lowercase hex chars) -- random, not
  derived from any hardware identifier (so it leaks nothing about the host and is
  trivially regenerated by deleting the file, e.g. to re-key a reimaged box).
* It persists to a small JSON file under the worker cache root (default
  ``~/.cache/alice/worker-device-id.json``). FIRST run writes a fresh id +
  flushes/fsyncs it; EVERY later run reads the SAME id back. A second process /
  run for the same cache root therefore registers as the SAME device.
* Per Alice address: a host that mines for two Alice addresses still has ONE
  device id (the device is the same physical box); the per-(address, device)
  scoring key composes the two. The store is keyed by a small ``slot`` (default
  ``"default"``) so a single host CAN run two independent worker identities (two
  cache slots) if an operator wants two logical devices on one box.

CREDIT-ONLY: nothing here reads/writes a secret, key, seed, token, or payout
address. The device id is a NON-secret stable random handle (it is sent to the
gateway as part of the public worker name). It is safe to log.
"""

from __future__ import annotations

import json
import os
import uuid
from dataclasses import dataclass
from pathlib import Path

from alice_acp.api_chat_gateway.worker_pull_protocol import validate_device_id

#: Default file the device id persists to (under the worker cache root).
DEFAULT_DEVICE_ID_FILENAME = "worker-device-id.json"
#: The schema marker stored alongside the id so a future scheme is distinguishable.
DEVICE_ID_FILE_VERSION = "alice-worker-device-id-v1"
#: The default slot. One slot == one logical device for a given cache root; an
#: operator can pass a distinct slot to run two logical devices on one host.
DEFAULT_DEVICE_SLOT = "default"


def _default_device_id_path() -> Path:
    return Path.home() / ".cache" / "alice" / DEFAULT_DEVICE_ID_FILENAME


def generate_device_id() -> str:
    """A fresh stable per-device id: ``uuid4().hex`` (32 lowercase hex chars).

    Random (not hardware-derived) so it leaks nothing and is regenerated simply by
    discarding the persisted value. Validated through the SAME shape gate the wire
    uses so a generated id is always a valid worker-name component.
    """
    return validate_device_id(uuid.uuid4().hex)


@dataclass(frozen=True, slots=True)
class DeviceIdentity:
    """A resolved per-device identity + whether this run CREATED it (first run)."""

    device_id: str
    slot: str
    path: Path
    created: bool

    def to_public_dict(self) -> dict[str, object]:
        return {
            "file_version": DEVICE_ID_FILE_VERSION,
            "device_id": self.device_id,
            "slot": self.slot,
            "path": str(self.path),
            "created_this_run": self.created,
        }


def load_or_create_device_id(
    *,
    path: Path | None = None,
    slot: str = DEFAULT_DEVICE_SLOT,
) -> DeviceIdentity:
    """Return the host's STABLE device id for ``slot``, creating it on first run.

    Idempotent: the FIRST call for a (path, slot) generates + persists a fresh
    ``uuid4().hex`` and returns ``created=True``; EVERY later call returns the SAME
    persisted id with ``created=False``. The file is a small JSON map of
    ``slot -> device_id`` so multiple logical devices can share one file. A
    corrupt/unreadable file for this slot is repaired in place by minting a fresh
    id for the slot (fail-soft: a damaged cache must never wedge the worker, and a
    new id simply registers as a new device). The write is flushed + fsynced so a
    crash right after first run does not lose the id (which would silently re-key
    the device on the next run).

    The id is validated through :func:`validate_device_id` before return so a
    hand-edited file can never inject an id that would break the worker name.
    """
    target = Path(path) if path is not None else _default_device_id_path()
    if target.is_dir():
        target = target / DEFAULT_DEVICE_ID_FILENAME
    target.parent.mkdir(parents=True, exist_ok=True)

    existing = _read_slot(target, slot)
    if existing is not None:
        return DeviceIdentity(device_id=existing, slot=slot, path=target, created=False)

    device_id = generate_device_id()
    _write_slot(target, slot, device_id)
    return DeviceIdentity(device_id=device_id, slot=slot, path=target, created=True)


def _read_slot(path: Path, slot: str) -> str | None:
    """The persisted, VALIDATED device id for ``slot``, or ``None`` if absent/bad."""
    if not path.exists():
        return None
    try:
        raw = path.read_text(encoding="utf-8")
    except OSError:
        return None
    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError:
        return None
    if not isinstance(parsed, dict):
        return None
    slots = parsed.get("slots")
    if not isinstance(slots, dict):
        return None
    value = slots.get(slot)
    if not isinstance(value, str):
        return None
    try:
        return validate_device_id(value)
    except ValueError:
        # A corrupt/invalid stored id for this slot -> treat as absent (re-mint).
        return None


def _write_slot(path: Path, slot: str, device_id: str) -> None:
    """Persist ``device_id`` for ``slot`` (merging with any existing slots).

    Read-modify-write so writing one slot never drops another, then flush + fsync
    so the id survives a crash. A write OSError raises so the caller surfaces a
    real persistence failure rather than silently re-minting next run.
    """
    payload: dict[str, object] = {"file_version": DEVICE_ID_FILE_VERSION, "slots": {}}
    if path.exists():
        try:
            current = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(current, dict) and isinstance(current.get("slots"), dict):
                payload["slots"] = dict(current["slots"])
        except (OSError, json.JSONDecodeError):
            payload["slots"] = {}
    slots = payload["slots"]
    assert isinstance(slots, dict)  # narrow for the type checker
    slots[slot] = device_id
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True, separators=(",", ":")))
        handle.flush()
        os.fsync(handle.fileno())
    # Atomic replace so a reader never sees a half-written file.
    os.replace(tmp, path)
